// chainFixtureRow is one raw stored row of a chain fixture.
type chainFixtureRow struct {
	version                uint32
	validFrom, txFrom, del types.Instant
	updated                types.Instant
	current                bool
}

// chainFixtures are the chain shapes every "history + current" door builds
// from (WP-21): unknown ID, current only, a deleted entity (history only, nil
// current), history + current (an inherited legacy ValidFrom, so the
// migration acts), the current row stored below a history row (version order
// reversed), and a re-imported life sharing a version number.
var chainFixtures = []struct {
	name string
	rows []chainFixtureRow
}{
	{"unknown", nil},
	{"current-only", []chainFixtureRow{{0, 100, 100, 0, 0, true}}},
	{"history-only-deleted", []chainFixtureRow{{0, 100, 100, 0, 0, false}, {1, 200, 200, 300, 200, false}}},
	{"history+current", []chainFixtureRow{{0, 100, 100, 0, 0, false}, {1, 100, 200, 0, 200, true}}},
	{"current-below-history", []chainFixtureRow{{0, 100, 100, 0, 0, false}, {2, 300, 300, 0, 300, false}, {1, 200, 150, 0, 150, true}}},
	{"duplicate-version", []chainFixtureRow{{0, 100, 100, 150, 0, false}, {0, 200, 200, 0, 0, true}}},
	{"untimed-first-in-history", []chainFixtureRow{{0, 0, 100, 0, 0, false}, {1, 200, 200, 0, 200, true}}},
	{"untimed-first-current", []chainFixtureRow{{0, 0, 100, 0, 0, true}}},
	{"untimed-first-deleted", []chainFixtureRow{{0, 0, 100, 0, 0, false}, {1, 200, 200, 300, 200, false}}},
}

func chainFixtureTemporal(r chainFixtureRow) *types.TemporalMetadata {
	return &types.TemporalMetadata{ValidFrom: r.validFrom, TxFrom: r.txFrom, DeletedAt: r.del, UpdatedAt: r.updated}
}

func newChainFixtureCore(t *testing.T) *Core {
	t.Helper()
	g, err := New(Config{Store: memory.New()})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	t.Cleanup(func() { _ = g.Close() })
	g.temporalMetaHistory = nil // the full-chain arms are the inline builders under test
	g.txTimeQuery = nil         // as-of resolves through the chain, not the store capability
	return g
}

func chainNodeVersions(chain []*types.Node) string {
	parts := make([]string, 0, len(chain))
	for _, n := range chain {
		parts = append(parts, nodeRowString(n))
	}
	return "[" + strings.Join(parts, " | ") + "]"
}

func chainRelVersions(chain []*types.Relationship) string {
	parts := make([]string, 0, len(chain))
	for _, r := range chain {
		parts = append(parts, relRowString(r))
	}
	return "[" + strings.Join(parts, " | ") + "]"
}

func chainOrErr[T any](v T, err error, show func(T) string) string {
	if err != nil {
		return "err " + err.Error()
	}
	return show(v)
}

// chainDoorsNodeReport runs every node door that builds "history + current"
// on fixture rows and renders what each answered.
func chainDoorsNodeReport(t *testing.T, rows []chainFixtureRow) string {
	t.Helper()
	g := newChainFixtureCore(t)
	id := types.NodeID(1 << 30)
	put := func(g *Core) {
		for i, r := range rows {
			n := types.NewNode(id, 1, nil)
			n.SetVersion(r.version)
			n.SetTemporal(chainFixtureTemporal(r))
			_ = n.SetProperty("row", int64(i))
			var err error
			if r.current {
				err = g.store.PutNode(n)
			} else {
				err = g.store.PutNodeVersion(id, r.version, n)
			}
			if err != nil {
				t.Fatalf("put row %d: %v", i, err)
			}
		}
	}
	put(g)
	var b strings.Builder
	one := func(n *types.Node) string { return nodeRowString(n) }
	chain, err := g.nodeChainOf(id)
	fmt.Fprintf(&b, "chainOf=%s\n", chainOrErr(chain, err, chainNodeVersions))
	for _, tx := range []types.Instant{0, 160} {
		for _, v := range []types.Instant{150, 250, 350} {
			cur, _ := g.getCurrentNode(id)
			n, err := g.nodeAtFullChain(entityReads{c: g, scan: true}, id, cur, v, tx)
			fmt.Fprintf(&b, "at(v=%d,tx=%d)=%s\n", v, tx, chainOrErr(n, err, one))
		}
		n, err := g.findNodeVersionMatchingDuringTx(id, 0, 1000, tx, nil)
		fmt.Fprintf(&b, "during(tx=%d)=%s\n", tx, chainOrErr(n, err, one))
	}
	for _, tx := range []types.Instant{0, 160, 1000} {
		n, err := g.nodeAsOfLocked(id, tx)
		fmt.Fprintf(&b, "asOf(tx=%d)=%s\n", tx, chainOrErr(n, err, one))
	}
	n, err := g.findNodeVersionRelating(id, 0, 1000, types.AllRelations(), nil)
	fmt.Fprintf(&b, "relating=%s\n", chainOrErr(n, err, one))
	segs, err := g.nodeEffectiveTimelineFrom(entityReads{c: g, scan: true}, id, 0)
	fmt.Fprintf(&b, "effective=%s\n", chainOrErr(segs, err, nodeSegmentsString))

	m := newChainFixtureCore(t)
	put(m)
	if err := m.migrateNodeHistoryClearInheritedValidFrom(); err != nil {
		fmt.Fprintf(&b, "migrate=err %v\n", err)
	} else {
		chain, err := m.nodeChainOf(id)
		fmt.Fprintf(&b, "migrated=%s\n", chainOrErr(chain, err, chainNodeVersions))
	}

	u := newChainFixtureCore(t)
	put(u)
	if err := u.stampNodeFirstVersion(id); err != nil {
		fmt.Fprintf(&b, "stamp=err %v\n", err)
	} else {
		chain, err := u.nodeChainOf(id)
		fmt.Fprintf(&b, "stamped=%s\n", chainOrErr(chain, err, chainNodeVersions))
	}
	return b.String()
}

// chainDoorsRelReport is chainDoorsNodeReport for relationships.
func chainDoorsRelReport(t *testing.T, rows []chainFixtureRow) string {
	t.Helper()
	g := newChainFixtureCore(t)
	id := types.RelID(1 << 30)
	put := func(g *Core) {
		for _, end := range []types.NodeID{2, 3} {
			if err := g.store.PutNode(types.NewNode(end, 1, nil)); err != nil {
				t.Fatalf("put endpoint %d: %v", end, err)
			}
		}
		for i, r := range rows {
			rel := types.NewRelationship(id, 1, 2, 3)
			rel.SetVersion(r.version)
			rel.SetTemporal(chainFixtureTemporal(r))
			_ = rel.SetProperty("row", int64(i))
			var err error
			if r.current {
				err = g.store.PutRelationship(rel)
			} else {
				err = g.store.PutRelVersion(id, r.version, rel)
			}
			if err != nil {
				t.Fatalf("put row %d: %v", i, err)
			}
		}
	}
	put(g)
	var b strings.Builder
	one := func(r *types.Relationship) string { return relRowString(r) }
	chain, err := g.relChainOf(id)
	fmt.Fprintf(&b, "chainOf=%s\n", chainOrErr(chain, err, chainRelVersions))
	for _, tx := range []types.Instant{0, 160} {
		for _, v := range []types.Instant{150, 250, 350} {
			cur, _ := g.getCurrentRelationship(id)
			r, err := g.relAtFromCurrent(entityReads{c: g, scan: true}, id, cur, v, tx)
			fmt.Fprintf(&b, "at(v=%d,tx=%d)=%s\n", v, tx, chainOrErr(r, err, one))
		}
		r, err := g.findRelVersionMatchingDuringTx(id, 0, 1000, tx, nil)
		fmt.Fprintf(&b, "during(tx=%d)=%s\n", tx, chainOrErr(r, err, one))
	}
	for _, tx := range []types.Instant{0, 160, 1000} {
		r, err := g.relAsOfLocked(id, tx)
		fmt.Fprintf(&b, "asOf(tx=%d)=%s\n", tx, chainOrErr(r, err, one))
	}
	r, err := g.findRelVersionRelating(id, 0, 1000, types.AllRelations(), nil)
	fmt.Fprintf(&b, "relating=%s\n", chainOrErr(r, err, one))
	segs, err := g.relEffectiveTimelineFrom(entityReads{c: g, scan: true}, id, 0)
	fmt.Fprintf(&b, "effective=%s\n", chainOrErr(segs, err, relSegmentsString))

	m := newChainFixtureCore(t)
	put(m)
	if err := m.migrateRelHistoryClearInheritedValidFrom(); err != nil {
		fmt.Fprintf(&b, "migrate=err %v\n", err)
	} else {
		chain, err := m.relChainOf(id)
		fmt.Fprintf(&b, "migrated=%s\n", chainOrErr(chain, err, chainRelVersions))
	}

	u := newChainFixtureCore(t)
	put(u)
	if err := u.stampRelFirstVersion(id); err != nil {
		fmt.Fprintf(&b, "stamp=err %v\n", err)
	} else {
		chain, err := u.relChainOf(id)
		fmt.Fprintf(&b, "stamped=%s\n", chainOrErr(chain, err, chainRelVersions))
	}
	return b.String()
}

// TestChainDoorsCharacterization pins what every door that built its own
// "history + current" chain answers on each chain shape (as-of point, during,
// relating, effective timeline, any-version chain, legacy ValidFrom
// migration, untimed first-version stamp), recorded before WP-21 folded the builders into chainOf.
func TestChainDoorsCharacterization(t *testing.T) {
	for _, fx := range chainFixtures {
		t.Run(fx.name, func(t *testing.T) {
			if got, want := chainDoorsNodeReport(t, fx.rows), chainDoorsGolden["node/"+fx.name]; got != want {
				t.Errorf("node doors changed:\n got:\n%s\nwant:\n%s", got, want)
			}
			if got, want := chainDoorsRelReport(t, fx.rows), chainDoorsGolden["rel/"+fx.name]; got != want {
				t.Errorf("rel doors changed:\n got:\n%s\nwant:\n%s", got, want)
			}
		})
	}
}

